def _add_complex_section(self, item):
        """Add a section that has a filter and set of constraints

        :raise: ValueError if filter or constraints is missing
        """
        if not item.get('filter'):
            raise ValueError('Missing filter in complex section')
        if not item.get('constraints'):
            raise ValueError('Missing constraints in complex section')
        self.add_section(item['filter'], item['constraints'])

